import 'klic-design/motions/runtime.css';
import recipe from 'klic-design/motions/tr-whip';
const host=document.querySelector('[data-klic-motion-root]');
if(!host)throw new Error('Add a [data-klic-motion-root] element before mounting.');
const motion=mountMotion(host,recipe);
void motion.ready.catch(error=>{if(host?.isConnected)host.dataset.motionError=error instanceof Error?error.message:String(error);});
export default motion;

implementation.react:
import {useEffect,useRef} from 'react';
import {mountMotion} from 'klic-design/motions/runtime';
import 'klic-design/motions/runtime.css';
import recipe from 'klic-design/motions/tr-whip';

export function MotionPreview(){
  const host=useRef(null);
  useEffect(()=>{const node=host.current;if(!node)return;const motion=mountMotion(node,recipe);void motion.ready.catch(error=>{if(node.isConnected)node.dataset.motionError=error instanceof Error?error.message:String(error);});return ()=>motion.destroy();},[]);
  return <div ref={host} className="motion-source-stage" aria-label={"Whip Pan"}/>;
}

